#!/usr/bin/env python3
"""Apply only hash-pinned Qodana R2 packets. Default: validate/diff, no writes."""
from __future__ import annotations
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

class PlanError(RuntimeError):
    pass

def blob_sha(data: bytes) -> str:
    return hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest()

def code_tokens(text: str):
    """C# identifiers outside comments, chars and strings; interpolation is opaque.

    This limited lexer is sufficient for the reviewed private-field packets.
    None of their renamed fields occurs inside a string interpolation. It is
    deliberately not a general-purpose C# refactoring engine.
    """
    i, n = 0, len(text)
    while i < n:
        if text.startswith('//', i):
            end = text.find('\n', i + 2); i = n if end < 0 else end; continue
        if text.startswith('/*', i):
            end = text.find('*/', i + 2)
            if end < 0: raise PlanError('Unterminated block comment')
            i = end + 2; continue
        m = re.match(r'\$*"{3,}', text[i:])
        if m:
            marker = '"' * m.group().count('"')
            end = text.find(marker, i + len(m.group()))
            if end < 0: raise PlanError('Unterminated raw string')
            i = end + len(marker); continue
        prefix = next((p for p in ('$@"', '@$"', '@"', '$"', '"', "'") if text.startswith(p, i)), None)
        if prefix:
            quote = "'" if prefix == "'" else '"'
            verbatim = '@' in prefix
            i += len(prefix)
            while i < n:
                if text[i] == quote:
                    if verbatim and i + 1 < n and text[i + 1] == quote:
                        i += 2; continue
                    i += 1; break
                if not verbatim and text[i] == '\\': i += 2
                else: i += 1
            else: raise PlanError('Unterminated string or character literal')
            continue
        if text[i].isalpha() or text[i] == '_':
            end = i + 1
            while end < n and (text[end].isalnum() or text[end] == '_'): end += 1
            yield (i, end, text[i:end]); i = end
        else: i += 1

def bounds(text: str, operation: dict) -> tuple[int, int]:
    start_anchor = operation.get('scope_start')
    end_anchor = operation.get('scope_end')
    if start_anchor:
        if text.count(start_anchor) != 1: raise PlanError('Scope start is not unique')
        start = text.index(start_anchor)
    else: start = 0
    if end_anchor:
        offset = start + (len(start_anchor) if start_anchor else 0)
        tail = text[offset:]
        if tail.count(end_anchor) != 1: raise PlanError('Scope end is not unique')
        end = offset + tail.index(end_anchor)
    else: end = len(text)
    return start, end

def transform(text: str, operations: list[dict]) -> str:
    for operation in operations:
        start, end = bounds(text, operation)
        region = text[start:end]
        old, new = operation['old'], operation['new']
        expected = operation['count']
        if not isinstance(expected, int) or expected < 1: raise PlanError('Invalid count')
        if operation['kind'] == 'replace':
            count = region.count(old)
            if count != expected: raise PlanError(f'Exact preimage count {count} != {expected}: {old!r}')
            region = region.replace(old, new)
        elif operation['kind'] in ('identifier', 'member'):
            if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', old) or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', new):
                raise PlanError('Invalid identifier')
            matches = [(a, b) for a, b, value in code_tokens(region) if value == old and
                (operation['kind'] == 'identifier' or region[b:].lstrip().startswith('.'))]
            if len(matches) != expected: raise PlanError(f'Identifier count {len(matches)} != {expected}: {old}')
            # No string-producing nameof change is approved for these alpha-renames.
            if re.search(r'\bnameof\s*\(\s*' + re.escape(old) + r'\s*\)', region):
                raise PlanError(f'Unexpected name-dependent expression: {old}')
            for a, b in reversed(matches): region = region[:a] + new + region[b:]
        else: raise PlanError('Unrecognized operation')
        text = text[:start] + region + text[end:]
    return text

def prepare_file(root: Path, spec: dict) -> tuple[Path, bytes, bytes]:
    relative = Path(spec['path'])
    if relative.is_absolute() or '..' in relative.parts or '.git' in relative.parts:
        raise PlanError('Unsafe repository path')
    path = root / relative
    if any((root.joinpath(*relative.parts[:i])).is_symlink() for i in range(1, len(relative.parts)+1)):
        raise PlanError('Symlink target is not approved')
    original = path.read_bytes()
    if blob_sha(original) != spec['git_blob_sha']:
        raise PlanError(f'Changed/already-applied source: {relative}. Do not alter expected hashes or fuzzy-apply.')
    bom = original.startswith(b'\xef\xbb\xbf')
    text = original.decode('utf-8-sig')
    crlf = '\r\n' in text
    if '\r' in text.replace('\r\n', '') or (crlf and '\n' in text.replace('\r\n', '')):
        raise PlanError('Mixed/unsupported newline format')
    canonical = text.replace('\r\n', '\n')
    updated = transform(canonical, spec['operations'])
    if updated == canonical: raise PlanError('Empty transformation')
    if crlf: updated = updated.replace('\n', '\r\n')
    result = (b'\xef\xbb\xbf' if bom else b'') + updated.encode('utf-8')
    return path, original, result

def atomic_write(path: Path, data: bytes) -> None:
    mode = path.stat().st_mode & 0o777
    fd, temp = tempfile.mkstemp(prefix='.qodana-r2-', dir=path.parent)
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(data); stream.flush(); os.fsync(stream.fileno())
        os.chmod(temp, mode)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp): os.unlink(temp)

def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', required=True, type=Path)
    parser.add_argument('--plan', required=True, type=Path)
    parser.add_argument('--packet', required=True)
    parser.add_argument('--apply', action='store_true')
    args = parser.parse_args()
    root = args.repo.resolve()
    def git(*items):
        return subprocess.check_output(['git', '-C', str(root), *items], text=True).strip()
    if Path(git('rev-parse', '--show-toplevel')).resolve() != root:
        raise PlanError('Use the repository root')
    if git('status', '--porcelain'):
        raise PlanError('Worktree must be clean; keep audit files outside it. Commit fixed tests first.')
    plan = json.loads(args.plan.read_text(encoding='utf-8'))
    if plan.get('schema_version') != 2 or plan.get('repository') != 'NYGsatoshi/Coglatas':
        raise PlanError('Unexpected plan/repository')
    subprocess.run(['git', '-C', str(root), 'merge-base', '--is-ancestor', plan['audit_source_sha'], 'HEAD'], check=True)
    candidates = [p for p in plan['packets'] if p['id'] == args.packet]
    if len(candidates) != 1: raise PlanError('Unknown/duplicate packet')
    packet = candidates[0]
    paths = [p['path'] for p in packet['files']]
    if len(paths) != len(set(paths)): raise PlanError('Duplicate file entry')
    changes = [prepare_file(root, spec) for spec in packet['files']]  # all preflight before any write
    if args.apply:
        written = []
        try:
            for path, original, result in changes:
                written.append((path, original)); atomic_write(path, result)
        except BaseException:
            for path, original in reversed(written): atomic_write(path, original)
            raise
    print(json.dumps({'packet': args.packet, 'applied': args.apply,
       'files': [{'path': str(path.relative_to(root)), 'before': blob_sha(before), 'after': blob_sha(after)}
                 for path, before, after in changes]}, indent=2))
    return 0

if __name__ == '__main__':
    try: raise SystemExit(main())
    except (PlanError, OSError, ValueError, KeyError, subprocess.CalledProcessError) as exc:
        print(f'STOP: {exc}', file=sys.stderr); raise SystemExit(2)

